import os, time, random, requests

BASE = "https://api.example.com/v1/orders"
HEADERS = {"Authorization": f"Bearer {os.environ['ORDERS_TOKEN']}"}

def get_with_retry(params, max_retries=5):
    for attempt in range(max_retries + 1):
        r = requests.get(BASE, headers=HEADERS, params=params, timeout=30)
        if r.status_code == 429 or r.status_code >= 500:
            wait = float(r.headers.get("Retry-After", min(60, 2 ** attempt)))
            time.sleep(wait + random.uniform(0, 0.5))
            continue
        r.raise_for_status()
        return r.json()
    raise RuntimeError("gave up after retries")

orders, cursor = [], None
while True:
    page = get_with_retry({"limit": 100, **({"cursor": cursor} if cursor else {})})
    orders.extend(page["data"])
    cursor = page.get("next_cursor")
    if not cursor:
        break

